fn allocate(&mut self, matcher: &M) -> io::Result<&mut Space<M>> {
    if self.space.is_none() {
        let caps =
            matcher.new_captures().map_err(io::Error::error_message)?;
        self.space = Some(Space { caps, dst: vec![], matches: vec![] });
    }
    Ok(self.space.as_mut().unwrap())
}

