10	/**
11	 * Handles Astro Action requests in both modes:
12	 *
13	 * - **RPC**: POST requests to `/_actions/<name>` (originating from the
14	 *   generated JS client). Runs the action and returns the serialized result
15	 *   as the response, so the caller can short-circuit rendering.
16	 * - **Form**: POST requests with `?_action=<name>` targeting a page route
17	 *   (originating from an HTML `<form action={actions.foo}>`). Runs the
18	 *   action, stashes the result into `locals._actionPayload`, and returns
19	 *   `undefined` so the caller continues to render the page.
20	 *
21	 * Non-action requests are a no-op (`undefined`).
22	 *
23	 * This handler is invoked at the bottom of the middleware chain, before
24	 * page dispatch. That placement preserves the existing behavior where
25	 * user middleware sees action requests and response finalization (cookies,
26	 * sessions, etc.) runs around the action response.
27	 *
28	 * Expects the APIContext that is already being used by the render pipeline.
29	 * Returns a `Response` when the action fully handles the request (RPC),
30	 * or `undefined` when the caller should continue processing the request
31	 * (form actions or non-action requests).
32	 */
33	export function handleAction(
34		apiContext: APIContext,
35		state: FetchState,
36	): Promise<Response | undefined> | undefined {
37		markFeatureUsed(state.manifest, FetchFeatures.actions);
38		if (apiContext.isPrerendered) {
39			return undefined;
40		}
41	
42		const { action, setActionResult } = getActionContext(apiContext);
43		if (!action) {
44			return undefined;
45		}
46	
