53			isForbiddenCrossOriginRequest(apiContext.request, apiContext.url, apiContext.isPrerendered)
54		) {
55			return Promise.resolve(createCrossOriginForbiddenResponse(apiContext.request));
56		}
57	
58		return executeAction(action, setActionResult);
59	}
