61	async function executeAction(
62		action: ReturnType<typeof getActionContext>['action'],
63		setActionResult: ReturnType<typeof getActionContext>['setActionResult'],
64	): Promise<Response | undefined> {
65		const actionResult = await action!.handler();
66		const serialized = serializeActionResult(actionResult);
67	
68		if (action!.calledFrom === 'rpc') {
69			if (serialized.type === 'empty') {
70				return new Response(null, {
71					status: serialized.status,
72				});
73			}
74			return new Response(serialized.body, {
75				status: serialized.status,
76				headers: {
