export function getValidatedIpFromHeader(
	headerValue: string | string[] | null | undefined,
): string | undefined {
	const raw = getFirstForwardedValue(headerValue);
	if (raw && isValidIpAddress(raw)) {
		return raw;
	}
	return undefined;
}

